//! UTF-16 String methods. Indexing and padding count code units, not scalars.
use crate::{Runtime,Value,JsError,JsResult,EnvId,ObjectKind};
use crate::closures::NativeFn;
fn arg(a:&[Value],i:usize)->Value{a.get(i).copied().unwrap_or(Value::Undefined)}
fn integer(rt:&mut Runtime,v:Value)->JsResult<f64>{let n=rt.to_number(v)?;Ok(if n.is_nan(){0.0}else{n.trunc()})}
fn source(rt:&mut Runtime,v:Value)->JsResult<Vec<u16>>{rt.require_object_coercible(v)?;let id=rt.to_string(v)?;Ok(rt.string_units(id).to_vec())}
fn relative(n:f64,len:usize)->usize{if n<0.0{(len as f64+n).max(0.0)as usize}else{n.min(len as f64)as usize}}
fn bounded(n:f64,len:usize)->usize{n.max(0.0).min(len as f64)as usize}
impl Runtime{
 pub fn install_string_builtins(&mut self)->JsResult<()>{let p=Value::Object(self.string_prototype);for(name,n,code)in[("charAt",1,char_at as NativeFn),("charCodeAt",1,char_code_at as NativeFn),("codePointAt",1,code_point_at as NativeFn),("slice",2,slice as NativeFn),("substring",2,substring as NativeFn),("substr",2,substr as NativeFn),("indexOf",1,index_of as NativeFn),("lastIndexOf",1,last_index_of as NativeFn),("includes",1,includes as NativeFn),("startsWith",1,starts_with as NativeFn),("endsWith",1,ends_with as NativeFn),("concat",1,concat as NativeFn),("repeat",1,repeat as NativeFn),("padStart",1,pad_start as NativeFn),("padEnd",1,pad_end as NativeFn),("trim",0,trim as NativeFn),("trimStart",0,trim_start as NativeFn),("trimEnd",0,trim_end as NativeFn),("toLowerCase",0,lower as NativeFn),("toUpperCase",0,upper as NativeFn)]{self.builtin(p,name,n,code)?;}for(name,original)in[("trimLeft","trimStart"),("trimRight","trimEnd")]{let key=self.string(original);let value=self.get(p,key)?;let key=self.string(name);self.define_data(p,key,value,true,false,true)?;}let global=Value::Object(self.global_object);let key=self.string("String");let c=self.get(global,key)?;self.builtin(c,"fromCharCode",1,from_char_code)?;self.builtin(c,"fromCodePoint",1,from_code_point)?;Ok(())}
}
fn char_at(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{let s=source(rt,this)?;let n=integer(rt,arg(a,0))?;Ok(if n<0.0||n>=s.len()as f64{rt.string("")}else{rt.string_utf16(&s[n as usize..n as usize+1])})}
fn char_code_at(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{let s=source(rt,this)?;let n=integer(rt,arg(a,0))?;Ok(Value::Number(if n<0.0||n>=s.len()as f64{crate::value::CONVERSION_NAN}else{s[n as usize]as f64}))}
fn code_point_at(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{let s=source(rt,this)?;let n=integer(rt,arg(a,0))?;if n<0.0||n>=s.len()as f64{return Ok(Value::Undefined)}let n=n as usize;let v=if (0xd800..=0xdbff).contains(&s[n])&&n+1<s.len()&&(0xdc00..=0xdfff).contains(&s[n+1]){0x10000+((s[n]as u32-0xd800)<<10)+(s[n+1]as u32-0xdc00)}else{s[n]as u32};Ok(Value::Number(v as f64))}
fn slice(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{let s=source(rt,this)?;let begin=relative(integer(rt,arg(a,0))?,s.len());let end=if matches!(arg(a,1),Value::Undefined){s.len()}else{relative(integer(rt,a[1])?,s.len())};Ok(rt.string_utf16(&s[begin..end.max(begin)]))}
fn substring(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{let s=source(rt,this)?;let begin=bounded(integer(rt,arg(a,0))?,s.len());let end=if matches!(arg(a,1),Value::Undefined){s.len()}else{bounded(integer(rt,a[1])?,s.len())};Ok(rt.string_utf16(&s[begin.min(end)..begin.max(end)]))}
fn substr(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{let s=source(rt,this)?;let begin=relative(integer(rt,arg(a,0))?,s.len());let len=if matches!(arg(a,1),Value::Undefined){s.len()-begin}else{bounded(integer(rt,a[1])?,s.len()-begin)};Ok(rt.string_utf16(&s[begin..begin+len]))}
fn index_of(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{let s=source(rt,this)?;let needle=rt.to_string(arg(a,0))?;let needle=rt.string_units(needle).to_vec();let start=bounded(integer(rt,arg(a,1))?,s.len());let found=if needle.is_empty(){Some(start)}else{s[start..].windows(needle.len()).position(|w|w==needle).map(|i|i+start)};Ok(Value::Number(found.map(|i|i as f64).unwrap_or(-1.0)))}
fn last_index_of(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{let s=source(rt,this)?;let needle=rt.to_string(arg(a,0))?;let needle=rt.string_units(needle).to_vec();let raw=rt.to_number(arg(a,1))?;let start=if raw.is_nan(){s.len()}else{bounded(raw.trunc(),s.len())};if needle.is_empty(){return Ok(Value::Number(start as f64))}for i in(0..=start.min(s.len().saturating_sub(needle.len()))).rev(){if s.get(i..i+needle.len())==Some(&needle[..]){return Ok(Value::Number(i as f64))}}Ok(Value::Number(-1.0))}
fn search_string(rt:&mut Runtime,v:Value)->JsResult<Vec<u16>>{if rt.object_id(v).is_ok_and(|id|matches!(rt.objects[id.0].kind,ObjectKind::RegExp(_))){return Err(JsError::TypeError("String search method does not accept a RegExp".into()))}let id=rt.to_string(v)?;Ok(rt.string_units(id).to_vec())}
fn includes(rt:&mut Runtime,this:Value,a:&[Value],env:EnvId)->JsResult<Value>{let s=source(rt,this)?;let n=search_string(rt,arg(a,0))?;let p=bounded(integer(rt,arg(a,1))?,s.len());let result=if n.is_empty(){true}else{s[p..].windows(n.len()).any(|w|w==n)};let _=env;Ok(Value::Bool(result))}
fn starts_with(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{let s=source(rt,this)?;let n=search_string(rt,arg(a,0))?;let p=bounded(integer(rt,arg(a,1))?,s.len());Ok(Value::Bool(s.get(p..p+n.len())==Some(&n[..])))}
fn ends_with(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{let s=source(rt,this)?;let n=search_string(rt,arg(a,0))?;let p=if matches!(arg(a,1),Value::Undefined){s.len()}else{bounded(integer(rt,a[1])?,s.len())};Ok(Value::Bool(p>=n.len()&&s.get(p-n.len()..p)==Some(&n[..])))}
fn concat(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{let mut s=source(rt,this)?;for v in a{let id=rt.to_string(*v)?;s.extend_from_slice(rt.string_units(id));}Ok(rt.string_utf16(&s))}
fn repeat(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{let s=source(rt,this)?;let n=integer(rt,arg(a,0))?;if n<0.0||!n.is_finite(){return Err(JsError::RangeError("invalid count value".into()))}if s.is_empty(){return Ok(rt.string(""))}if n>1_000_000.0||s.len().saturating_mul(n as usize)>16_000_000{return Err(JsError::Unsupported("String.repeat exceeds resource bound".into()))}Ok(rt.string_utf16(&s.repeat(n as usize)))}
fn pad(rt:&mut Runtime,this:Value,a:&[Value],start:bool)->JsResult<Value>{let s=source(rt,this)?;let n=integer(rt,arg(a,0))?.max(0.0);if n<=s.len()as f64{return Ok(rt.string_utf16(&s))}if n>16_000_000.0{return Err(JsError::Unsupported("String padding exceeds resource bound".into()))}let filler=if matches!(arg(a,1),Value::Undefined){vec![32]}else{let id=rt.to_string(a[1])?;rt.string_units(id).to_vec()};if filler.is_empty(){return Ok(rt.string_utf16(&s))}let missing=n as usize-s.len();let fill=(0..missing).map(|i|filler[i%filler.len()]).collect::<Vec<_>>();let mut result=if start{fill.clone()}else{s.clone()};result.extend_from_slice(if start{&s}else{&fill});Ok(rt.string_utf16(&result))}
fn pad_start(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{pad(rt,this,a,true)}
fn pad_end(rt:&mut Runtime,this:Value,a:&[Value],_:EnvId)->JsResult<Value>{pad(rt,this,a,false)}
fn whitespace(c:u16)->bool{matches!(c,0x0009..=0x000d|0x0020|0x00a0|0x1680|0x2000..=0x200a|0x2028|0x2029|0x202f|0x205f|0x3000|0xfeff)}
fn trim_kind(rt:&mut Runtime,this:Value,left:bool,right:bool)->JsResult<Value>{let s=source(rt,this)?;let mut a=0;let mut b=s.len();if left{while a<b&&whitespace(s[a]){a+=1}}if right{while b>a&&whitespace(s[b-1]){b-=1}}Ok(rt.string_utf16(&s[a..b]))}
fn trim(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{trim_kind(rt,this,true,true)}
fn trim_start(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{trim_kind(rt,this,true,false)}
fn trim_end(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{trim_kind(rt,this,false,true)}
fn change_case(rt:&mut Runtime,this:Value,upper:bool)->JsResult<Value>{if std::char::UNICODE_VERSION!=(17,0,0){return Err(JsError::Unsupported("case conversion requires pinned Unicode 17 tables".into()))}let s=source(rt,this)?;let mut output=Vec::new();let mut segment=String::new();let flush=|segment:&mut String,output:&mut Vec<u16>|{let mapped=if upper{segment.to_uppercase()}else{segment.to_lowercase()};output.extend(mapped.encode_utf16());segment.clear();};for decoded in std::char::decode_utf16(s){match decoded{Ok(c)=>segment.push(c),Err(error)=>{flush(&mut segment,&mut output);output.push(error.unpaired_surrogate());}}}flush(&mut segment,&mut output);Ok(rt.string_utf16(&output))}
fn lower(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{change_case(rt,this,false)}
fn upper(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{change_case(rt,this,true)}
fn from_char_code(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{let mut s=Vec::new();for v in a{s.push((rt.to_uint32(*v)?&0xffff)as u16);}Ok(rt.string_utf16(&s))}
fn from_code_point(rt:&mut Runtime,_:Value,a:&[Value],_:EnvId)->JsResult<Value>{let mut s=Vec::new();for v in a{let n=rt.to_number(*v)?;if n.fract()!=0.0||!(0.0..=0x10ffff as f64).contains(&n){return Err(JsError::RangeError("invalid code point".into()))}let n=n as u32;if n<=0xffff{s.push(n as u16)}else{let n=n-0x10000;s.push(0xd800+(n>>10)as u16);s.push(0xdc00+(n&1023)as u16);}}Ok(rt.string_utf16(&s))}
